1. import { CssSelectorParser } from 'css-selector-parser';
2. import { escapeRegExp } from 'lodash';
3. import { errors } from 'appium/driver';
4. 
5. const parser = new CssSelectorParser();
6. parser.registerSelectorPseudos('has');
7. parser.registerNestingOperators('>', '+', '~');
8. parser.registerAttrEqualityMods('^', '$', '*', '~');
9. parser.enableSubstitutes();
10. 
11. const RESOURCE_ID = 'resource-id';
12. const ID_LOCATOR_PATTERN = /^[a-zA-Z_][a-zA-Z0-9._]*:id\/[\S]+$/;
13. 
14. const BOOLEAN_ATTRS = [
15.   'checkable', 'checked', 'clickable', 'enabled', 'focusable',
16.   'focused', 'long-clickable', 'scrollable', 'selected',
17. ];
18. 
19. const NUMERIC_ATTRS = [
20.   'index', 'instance',
21. ];
22. 
23. const STR_ATTRS = [
24.   'description', RESOURCE_ID, 'text', 'class-name', 'package-name'
25. ];
26. 
27. const ALL_ATTRS = [
28.   ...BOOLEAN_ATTRS,
29.   ...NUMERIC_ATTRS,
30.   ...STR_ATTRS,
31. ];
32. 
33. const ATTRIBUTE_ALIASES = [
34.   [RESOURCE_ID, ['id']],
35.   ['description', [
36.     'content-description', 'content-desc',
37.     'desc', 'accessibility-id',
38.   ]],
39.   ['index', ['nth-child']],
40. ];
41. 
42. /**
43.  * Convert hyphen separated word to snake case
44.  *
45.  * @param {string} str
46.  * @returns {string} The hyphen separated word translated to snake case
47.  */
48. function toSnakeCase (str) {
49.   if (!str) {
50.     return '';
51.   }
52.   const tokens = str.split('-').map((str) => str.charAt(0).toUpperCase() + str.slice(1).toLowerCase());
53.   const out = tokens.join('');
54.   return out.charAt(0).toLowerCase() + out.slice(1);
55. }
56. 
57. /**
58.  * @typedef {Object} CssNameValueObject
59.  * @property {?name} name The name of the CSS object
60.  * @property {?string} value The value of the CSS object
61.  */
62. 
63. /**
64.  * Get the boolean from a CSS object. If empty, return true. If not true/false/empty, throw exception
65.  *
66.  * @param {CssNameValueObject} css A CSS object that has 'name' and 'value'
67.  * @returns {string} Either 'true' or 'false'. If value is empty, return 'true'
68.  */
69. function assertGetBool (css) {
70.   const val = css.value?.toLowerCase() || 'true'; // an omitted boolean attribute means 'true' (e.g.: input[checked] means checked is true)
71.   if (['true', 'false'].includes(val)) {
72.     return val;
73.   }
74.   throw new Error(`'${css.name}' must be true, false or empty. Found '${css.value}'`);
75. }
76. 
77. /**
78.  * Get the canonical form of a CSS attribute name
79.  *
80.  * Converts to lowercase and if an attribute name is an alias for something else, return
81.  * what it is an alias for
82.  *
83.  * @param {Object} css CSS object
84.  * @returns {string} The canonical attribute name
85.  */
86. function assertGetAttrName (css) {
87.   const attrName = css.name.toLowerCase();
88. 
89.   // Check if it's supported and if it is, return it
90.   if (ALL_ATTRS.includes(attrName)) {
91.     return attrName.toLowerCase();
92.   }
93. 
94.   // If attrName is an alias for something else, return that
95.   for (const [officialAttr, aliasAttrs] of ATTRIBUTE_ALIASES) {
96.     if (aliasAttrs.includes(attrName)) {
97.       return officialAttr;
98.     }
99.   }
100.   throw new Error(`'${attrName}' is not a valid attribute. ` +
101.     `Supported attributes are '${ALL_ATTRS.join(', ')}'`);
102. }
103. 
104. /**
105.  * Get a regex that matches a whole word. For the ~= CSS attribute selector.
106.  *
107.  * @param {string} word
108.  * @returns {string} A regex "word" matcher
109.  */
110. function getWordMatcherRegex (word) {
111.   return `\\b(\\w*${escapeRegExp(word)}\\w*)\\b`;
112. }
113. 
114. /**
115.  * @typedef {Object} CssAttr
116.  * @property {?string} valueType Type of attribute (must be string or empty)
117.  * @property {?string} value Value of the attribute
118.  * @property {?string} operator The operator between value and value type (=, *=, , ^=, $=)
119.  */
120. 
121. /**
122.  * @typedef {Object} CssRule
123.  * @property {?string} nestingOperator The nesting operator (aka: combinator https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_Selectors)
124.  * @property {?string} tagName The tag name (aka: type selector https://developer.mozilla.org/en-US/docs/Web/CSS/Type_selectors)
125.  * @property {?string[]} classNames An array of CSS class names
126.  * @property {?CssAttr[]} attrs An array of CSS attributes
127.  * @property {?CssPseudo[]} attrs An array of CSS pseudos
128.  * @property {?string} id CSS identifier
129.  * @property {?CssRule} rule A descendant of this CSS rule
130.  */
131. 
132. /**
133.  * @typedef {Object} CssObject
134.  * @property {?string} type Type of CSS object. 'rule', 'ruleset' or 'selectors'
135.  */
136. 
137. /**
138.  * @typedef {Object} CssPseudo
139.  * @property {?string} valueType The type of CSS pseudo selector (https://www.npmjs.com/package/css-selector-parser for reference)
140.  * @property {?string} name The name of the pseudo selector
141.  * @property {?string} value The value of the pseudo selector
142.  */
143. 
144. class CssConverter {
145. 
146.   constructor (selector, pkg) {
147.     this.selector = selector;
148.     this.pkg = pkg;
149.   }
150. 
151.   /**
152.    * Add `<pkgName>:id/` prefix to beginning of string if it's not there already
153.    *
154.    * @param {string} locator The initial locator
155.    * @returns {string} String with `<pkgName>:id/` prepended (if it wasn't already)
156.    */
157.   formatIdLocator (locator) {
158.     return ID_LOCATOR_PATTERN.test(locator)
159.       ? locator
160.       : `${this.pkg || 'android'}:id/${locator}`;
161.   }
162. 
163.   /**
164.    * Convert a CSS attribute into a UiSelector method call
165.    *
166.    * @param {CssAttr} cssAttr CSS attribute object
167.    * @returns {string} CSS attribute parsed as UiSelector
168.    */
169.   parseAttr (cssAttr) {
170.     if (cssAttr.valueType && cssAttr.valueType !== 'string') {
171.       throw new Error(`'${cssAttr.name}=${cssAttr.value}' is an invalid attribute. ` +
172.         `Only 'string' and empty attribute types are supported. Found '${cssAttr.valueType}'`);
173.     }
174.     const attrName = assertGetAttrName(cssAttr);
175.     const methodName = toSnakeCase(attrName);
176. 
177.     // Validate that it's a supported attribute
178.     if (!STR_ATTRS.includes(attrName) && !BOOLEAN_ATTRS.includes(attrName)) {
179.       throw new Error(`'${attrName}' is not supported. Supported attributes are ` +
180.         `'${[...STR_ATTRS, ...BOOLEAN_ATTRS].join(', ')}'`);
181.     }
182. 
183.     // Parse boolean, if it's a boolean attribute
184.     if (BOOLEAN_ATTRS.includes(attrName)) {
185.       return `.${methodName}(${assertGetBool(cssAttr)})`;
186.     }
187. 
188.     // Otherwise parse as string
189.     let value = cssAttr.value || '';
190.     if (attrName === RESOURCE_ID) {
191.       value = this.formatIdLocator(value);
192.     }
193.     if (value === '') {
194.       return `.${methodName}Matches("")`;
195.     }
196. 
197.     switch (cssAttr.operator) {
198.       case '=':
199.         return `.${methodName}("${value}")`;
200.       case '*=':
201.         if (['description', 'text'].includes(attrName)) {
202.           return `.${methodName}Contains("${value}")`;
203.         }
204.         return `.${methodName}Matches("${escapeRegExp(value)}")`;
205.       case '^=':
206.         if (['description', 'text'].includes(attrName)) {
207.           return `.${methodName}StartsWith("${value}")`;
208.         }
209.         return `.${methodName}Matches("^${escapeRegExp(value)}")`;
210.       case '$=':
211.         return `.${methodName}Matches("${escapeRegExp(value)}$")`;
212.       case '~=':
213.         return `.${methodName}Matches("${getWordMatcherRegex(value)}")`;
214.       default:
215.         // Unreachable, but adding error in case a new CSS attribute is added.
216.         throw new Error(`Unsupported CSS attribute operator '${cssAttr.operator}'. ` +
217.           ` '=', '*=', '^=', '$=' and '~=' are supported.`);
218.     }
219.   }
220. 
221.   /**
222.    * Convert a CSS pseudo class to a UiSelector
223.    *
224.    * @param {CssPseudo} cssPseudo CSS Pseudo class
225.    * @returns {string} Pseudo selector parsed as UiSelector
226.    */
227.   parsePseudo (cssPseudo) {
228.     if (cssPseudo.valueType && cssPseudo.valueType !== 'string') {
229.       throw new Error(`'${cssPseudo.name}=${cssPseudo.value}'. ` +
230.         `Unsupported css pseudo class value type: '${cssPseudo.valueType}'. Only 'string' type or empty is supported.`);
231.     }
232. 
233.     const pseudoName = assertGetAttrName(cssPseudo);
234. 
235.     if (BOOLEAN_ATTRS.includes(pseudoName)) {
236.       return `.${toSnakeCase(pseudoName)}(${assertGetBool(cssPseudo)})`;
237.     }
238. 
239.     if (NUMERIC_ATTRS.includes(pseudoName)) {
240.       return `.${pseudoName}(${cssPseudo.value})`;
241.     }
242.   }
243. 
244.   /**
245.    * Convert a CSS rule to a UiSelector
246.    * @param {CssRule} cssRule CSS rule definition
247.    */
248.   parseCssRule (cssRule) {
249.     const { nestingOperator } = cssRule;
250.     if (nestingOperator && nestingOperator !== ' ') {
251.       throw new Error(`'${nestingOperator}' is not a supported combinator. ` +
252.         `Only child combinator (>) and descendant combinator are supported.`);
253.     }
254. 
255.     let uiAutomatorSelector = 'new UiSelector()';
256.     if (cssRule.tagName && cssRule.tagName !== '*') {
257.       let androidClass = [cssRule.tagName];
258.       if (cssRule.classNames) {
259.         for (const cssClassNames of cssRule.classNames) {
260.           androidClass.push(cssClassNames);
261.         }
262.         uiAutomatorSelector += `.className("${androidClass.join('.')}")`;
263.       } else {
264.         uiAutomatorSelector += `.classNameMatches("${cssRule.tagName}")`;
265.       }
266.     } else if (cssRule.classNames) {
267.       uiAutomatorSelector += `.classNameMatches("${cssRule.classNames.join('\\.')}")`;
268.     }
269.     if (cssRule.id) {
270.       uiAutomatorSelector += `.resourceId("${this.formatIdLocator(cssRule.id)}")`;
271.     }
272.     if (cssRule.attrs) {
273.       for (const attr of cssRule.attrs) {
274.         uiAutomatorSelector += this.parseAttr(attr);
275.       }
276.     }
277.     if (cssRule.pseudos) {
278.       for (const pseudo of cssRule.pseudos) {
279.         uiAutomatorSelector += this.parsePseudo(pseudo);
280.       }
281.     }
282.     if (cssRule.rule) {
283.       uiAutomatorSelector += `.childSelector(${this.parseCssRule(cssRule.rule)})`;
284.     }
285.     return uiAutomatorSelector;
286.   }
287. 
288.   /**
289.    * Convert CSS object to UiAutomator2 selector
290.    * @param {CssObject} css CSS object
291.    * @returns {string} The CSS object parsed as a UiSelector
292.    */
293.   parseCssObject (css) {
294.     switch (css.type) {
295.       case 'rule':
296.         return this.parseCssRule(css);
297.       case 'ruleSet':
298.         return this.parseCssObject(css.rule);
299.       case 'selectors':
300.         return css.selectors.map((selector) => this.parseCssObject(selector)).join('; ');
301. 
302.       default:
303.         // This is never reachable, but if it ever is do this.
304.         throw new Error(`UiAutomator does not support '${css.type}' css. Only supports 'rule', 'ruleSet', 'selectors' `);
305.     }
306.   }
307. 
308.   /**
309.    * Convert a CSS selector to a UiAutomator2 selector
310.    *
311.    * @returns {string} The CSS selector converted to a UiSelector
312.    */
313.   toUiAutomatorSelector () {
314.     let cssObj;
315.     try {
316.       cssObj = parser.parse(this.selector);
317.     } catch (e) {
318.       throw new errors.InvalidSelectorError(`Invalid CSS selector '${this.selector}'. Reason: '${e}'`);
319.     }
320.     try {
321.       return this.parseCssObject(cssObj);
322.     } catch (e) {
323.       throw new errors.InvalidSelectorError(`Unsupported CSS selector '${this.selector}'. Reason: '${e}'`);
324.     }
325.   }
326. }
327. 
328. export default CssConverter;

