1. import chai from 'chai';
2. import chaiAsPromised from 'chai-as-promised';
3. import CssConverter from '../../lib/css-converter';
4. 
5. chai.should();
6. chai.use(chaiAsPromised);
7. 
8. describe('css-converter.js', function () {
9.   describe('simple cases', function () {
10.     const simpleCases = [
11.       ['android.widget.TextView', 'new UiSelector().className("android.widget.TextView")'],
12.       ['TextView', 'new UiSelector().classNameMatches("TextView")'],
13.       ['.TextView', 'new UiSelector().classNameMatches("TextView")'],
14.       ['.widget.TextView', 'new UiSelector().classNameMatches("widget\\.TextView")'],
15.       ['*[checkable=true]', 'new UiSelector().checkable(true)'],
16.       ['*[checkable]', 'new UiSelector().checkable(true)'],
17.       ['*:checked', 'new UiSelector().checked(true)'],
18.       ['*[checked]', 'new UiSelector().checked(true)'],
19.       ['TextView[description="Some description"]', 'new UiSelector().classNameMatches("TextView").description("Some description")'],
20.       ['*[description]', 'new UiSelector().descriptionMatches("")'],
21.       ['*[description^=blah]', 'new UiSelector().descriptionStartsWith("blah")'],
22.       ['*[description$=bar]', 'new UiSelector().descriptionMatches("bar$")'],
23.       ['*[description*=bar]', 'new UiSelector().descriptionContains("bar")'],
24.       ['#identifier[description=foo]', 'new UiSelector().resourceId("android:id/identifier").description("foo")'],
25.       ['*[id=foo]', 'new UiSelector().resourceId("android:id/foo")'],
26.       ['*[description$="hello [ ^ $ . | ? * + ( ) world"]', 'new UiSelector().descriptionMatches("hello \\[ \\^ \\$ \\. \\| \\? \\* \\+ \\( \\) world$")'],
27.       ['TextView:iNdEx(4)', 'new UiSelector().classNameMatches("TextView").index(4)'],
28.       ['*:long-clickable', 'new UiSelector().longClickable(true)'],
29.       ['*[lOnG-cLiCkAbLe]', 'new UiSelector().longClickable(true)'],
30.       ['*:nth-child(3)', 'new UiSelector().index(3)'],
31.       ['*:instance(3)', 'new UiSelector().instance(3)'],
32.       [
33.         'android.widget.TextView[checkable] android.widget.WidgetView[focusable]:nth-child(1)',
34.         'new UiSelector().className("android.widget.TextView").checkable(true).childSelector(new UiSelector().className("android.widget.WidgetView").focusable(true).index(1))'
35.       ],
36.       ['* *[clickable=true][focused]', 'new UiSelector().childSelector(new UiSelector().clickable(true).focused(true))'],
37.       [
38.         '*[clickable=true], *[clickable=false]',
39.         'new UiSelector().clickable(true); new UiSelector().clickable(false)',
40.       ],
41.       ['*[description~="word"]', 'new UiSelector().descriptionMatches("\\b(\\w*word\\w*)\\b")'],
42.       [
43.         'android.widget.ListView android.widget.TextView',
44.         'new UiSelector().className("android.widget.ListView").childSelector(new UiSelector().className("android.widget.TextView"))'
45.       ],
46.     ];
47.     for (const [cssSelector, uiAutomatorSelector] of simpleCases) {
48.       it(`should convert '${cssSelector}' to '${uiAutomatorSelector}'`, function () {
49.         new CssConverter(cssSelector).toUiAutomatorSelector().should.equal(uiAutomatorSelector);
50.       });
51.     }
52.   });
53.   describe('unsupported css', function () {
54.     const testCases = [
55.       ['*[checked="ItS ChEcKeD"]', /'checked' must be true, false or empty. Found 'ItS ChEcKeD'/],
56.       ['*[foo="bar"]', /'foo' is not a valid attribute. Supported attributes are */],
57.       ['*:checked("ischecked")', /'checked' must be true, false or empty. Found 'ischecked'/],
